using System.ComponentModel;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Shapes;
using System.Windows.Threading;
using DeskCanvas.App.Services;
using WpfPath=System.Windows.Shapes.Path;
using WpfColor=System.Windows.Media.Color;
namespace DeskCanvas.App.Windows;
internal static class V18VisualBehavior
{
 [System.Runtime.CompilerServices.ModuleInitializer]internal static void Install()=>EventManager.RegisterClassHandler(typeof(FrameworkElement),FrameworkElement.LoadedEvent,new RoutedEventHandler(Loaded));
 private static void Loaded(object sender,RoutedEventArgs _){if(sender is StackPanel panel)Center(panel);if(sender is Rectangle art)Palette(art);if(sender is WpfPath path)Spark(path);}
 private static void Center(StackPanel old){if(old.Tag is string)return;var kids=old.Children.Cast<UIElement>().ToArray();if(kids.Length!=4||kids.Take(3).Any(x=>x is not Button)||kids[3] is not StackPanel bands||bands.Children.Count!=7)return;var parent=VisualTreeHelper.GetParent(old)as Grid;if(parent is null)return;var index=parent.Children.IndexOf(old);if(index<0)return;old.Tag="v18";var grid=new Grid{Height=old.Height,Margin=old.Margin,Tag="v18"};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(35)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(35)});var trio=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};for(var i=0;i<3;i++)trio.Children.Add(kids[i]);bands.Width=35;bands.Margin=new Thickness(0);bands.HorizontalAlignment=HorizontalAlignment.Right;grid.Children.Add(trio);Grid.SetColumn(trio,1);grid.Children.Add(bands);Grid.SetColumn(bands,2);Grid.SetRow(grid,Grid.GetRow(old));parent.Children.RemoveAt(index);parent.Children.Insert(index,grid);}
 private static void Palette(Rectangle art){if(art.Tag is string||art.Fill is not ImageBrush{ImageSource:BitmapSource image})return;try{var palette=Samples(image);if(!ArtworkPaletteMathV18.TryResolve(palette,out var colors))return;var card=Parent<Border>(art);if(card is null)return;art.Tag="v18";var a=WpfColor.FromRgb(colors.SurfaceA.R,colors.SurfaceA.G,colors.SurfaceA.B);var b=WpfColor.FromRgb(colors.SurfaceB.R,colors.SurfaceB.G,colors.SurfaceB.B);card.Background=new LinearGradientBrush(new GradientStopCollection{new GradientStop(WpfColor.FromArgb(255,a.R,a.G,a.B),0),new GradientStop(WpfColor.FromArgb(255,b.R,b.G,b.B),1)},135);card.Foreground=new SolidColorBrush(WpfColor.FromRgb(colors.Foreground.R,colors.Foreground.G,colors.Foreground.B));}catch{}}
 private static List<PaletteRgb> Samples(BitmapSource image){var width=Math.Max(1,image.PixelWidth);var height=Math.Max(1,image.PixelHeight);var bytes=new byte[width*height*4];image.CopyPixels(bytes,width*4,0);var step=Math.Max(1,Math.Min(width,height)/32);var result=new List<PaletteRgb>();for(var y=0;y<height;y+=step)for(var x=0;x<width;x+=step){var i=(y*width+x)*4;if(bytes[i+3]>=224)result.Add(new PaletteRgb(bytes[i+2],bytes[i+1],bytes[i]));}return result;}
 private static T? Parent<T>(DependencyObject item)where T:DependencyObject{for(var p=VisualTreeHelper.GetParent(item);p is not null;p=VisualTreeHelper.GetParent(p))if(p is T found)return found;return null;}
 private static void Spark(WpfPath path){if(path.Tag is string||path.StrokeThickness is not (>1 and <2)||Parent<Grid>(path)?.Children.OfType<TextBlock>().Any(x=>x.Text is "DOWN" or "UP")!=true)return;path.Tag="v18";var smooth=new Smoother(path);DependencyPropertyDescriptor.FromProperty(WpfPath.DataProperty,typeof(WpfPath)).AddValueChanged(path,smooth.TargetChanged);path.Unloaded+=(_,_)=>smooth.Dispose();path.IsVisibleChanged+=(_,e)=>{if(e.NewValue is false)smooth.Stop();};}
 private sealed class Smoother:IDisposable{private readonly WpfPath path;private readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(16)};private Point[] start=[],target=[];private TimeSpan time;private bool writing;internal Smoother(WpfPath path){this.path=path;timer.Tick+=Tick;}internal void TargetChanged(object? _,EventArgs __){if(writing||path.Data is not PathGeometry geometry)return;var points=geometry.Figures.SelectMany(f=>new[]{f.StartPoint}.Concat(f.Segments.OfType<LineSegment>().Select(s=>s.Point))).ToArray();if(points.Length<2)return;start=target.Length==points.Length?target:points;target=points;time=TimeSpan.Zero;if(path.IsVisible)timer.Start();}private void Tick(object? _,EventArgs __){time+=timer.Interval;var t=Math.Clamp(time.TotalMilliseconds/700,0,1);t=1-Math.Pow(1-t,3);var points=Enumerable.Range(0,target.Length).Select(i=>new Point(target[i].X+(start[i].X-target[i].X)*(1-t),Math.Clamp(target[i].Y+(start[i].Y-target[i].Y)*(1-t),0,16))).ToArray();var figure=new PathFigure{StartPoint=points[0]};for(var i=1;i<points.Length;i++){var previous=points[i-1];var point=points[i];var mid=(previous.X+point.X)/2;figure.Segments.Add(new BezierSegment(new Point(mid,previous.Y),new Point(mid,point.Y),point,true));}writing=true;path.Data=new PathGeometry([figure]);writing=false;if(t>=1)timer.Stop();}internal void Stop()=>timer.Stop();public void Dispose()=>timer.Stop();}
}
